import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import posterUrl from 'ext:ernestdefoe/marquee/forum/utils/posterUrl';
import ClubPanel from './ClubPanel';
import ClubEditModal from './ClubEditModal';
import { setMembership } from '../api';
import { t, text, monthName } from '../util';

/** One club: what it's on this month, everyone's progress, and its past picks. */
export default class ClubPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.club = null;
    app.store.find('clubs', m.route.param('id')).then(club => {
      this.club = club;
      app.setTitle(club.name());
      const latest = (club.picks() || [])[0];
      // The member list comes with the pick's own page.
      if (latest) app.store.find('club-picks', latest.id()).then(() => m.redraw());
      m.redraw();
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  view() {
    if (this.missing) return m("div", {
      className: "container ClubPage"
    }, m(Placeholder, {
      text: t('club.missing')
    }));
    if (!this.club) return m(LoadingIndicator, {
      display: "block"
    });
    const club = this.club;
    const picks = (club.picks() || []).filter(Boolean);
    const [latest, ...past] = picks;
    return m("div", {
      className: "container ClubPage"
    }, m("header", {
      className: "ClubPage-header"
    }, m("h1", null, club.name()), m("p", {
      className: "ClubPage-meta"
    }, t('clubs.members', {
      count: club.memberCount()
    })), club.description() ? m("p", {
      className: "ClubPage-description"
    }, club.description()) : null, m("div", {
      className: "ClubPage-controls"
    }, this.controls(club))), latest ? m("section", {
      className: "ClubPage-current"
    }, this.pickCard(latest), m(ClubPanel, {
      pick: latest,
      all: true
    })) : m(Placeholder, {
      text: t(club.canEdit() ? 'club.no_picks_host' : 'club.no_picks')
    }), past.length ? m("section", {
      className: "ClubPage-past"
    }, m("h2", null, t('club.past')), m("ul", {
      className: "ClubPicks"
    }, past.map(pick => m("li", null, this.pickCard(pick, true))))) : null);
  }
  pickCard(pick, small) {
    const media = pick.media();
    const discussion = pick.discussion();
    return m(Link, {
      className: small ? 'ClubPick ClubPick--small' : 'ClubPick',
      href: discussion ? app.route.discussion(discussion) : undefined
    }, media && media.poster() ? m("img", {
      src: posterUrl(media.poster(), small ? 'w185' : 'w342'),
      alt: "",
      loading: "lazy",
      decoding: "async"
    }) : m("span", {
      className: "ClubPick-blank"
    }), m("span", {
      className: "ClubPick-month"
    }, monthName(pick.month())), m("b", null, media ? media.title() : discussion ? discussion.title() : ''), small ? null : m("span", {
      className: "ClubPick-open"
    }, t('club.open_discussion')));
  }
  controls(club) {
    const items = [];
    if (app.session.user && club.viewerRole() !== 'host') {
      items.push(club.viewerRole() ? m(Button, {
        className: "Button",
        icon: "fas fa-user-minus",
        onclick: () => this.member(false)
      }, t('club.leave')) : club.canJoin() ? m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-user-plus",
        onclick: () => this.member(true)
      }, t('club.join')) : null);
    }
    if (club.canEdit()) {
      items.push(m(Button, {
        className: "Button",
        icon: "fas fa-pencil-alt",
        onclick: () => app.modal.show(ClubEditModal, {
          club
        })
      }, t('club.edit')), m(Button, {
        className: "Button Button--danger",
        icon: "far fa-trash-alt",
        onclick: () => this.remove()
      }, t('club.delete')));
      items.push(m("p", {
        className: "ClubPage-hint"
      }, t('club.how_to_pick')));
    }
    return items;
  }
  member(join) {
    setMembership(this.club, join).then(() => {
      const latest = (this.club.picks() || [])[0];
      return latest ? app.store.find('club-picks', latest.id()) : null;
    }).then(() => m.redraw());
  }
  remove() {
    if (!confirm(text('club.delete_confirm', {
      name: this.club.name()
    }))) return;
    app.request({
      method: 'DELETE',
      url: `${app.forum.attribute('apiUrl')}/clubs/${this.club.id()}`
    }).then(() => {
      app.store.remove(this.club);
      m.route.set(app.route('clubs'));
    });
  }
}
flarum.reg.add('ernestdefoe-club', 'forum/components/ClubPage', ClubPage);